import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def masks(ctx):
    inputs = torch.rand(16, generator=ctx.rng.torch)
    targets = torch.zeros(2, 4, 4)
    targets[0].reshape(-1)[:8] = 1
    targets[1].reshape(-1)[8:] = 1
    return {"inputs": synth.Tensor(inputs), "targets": synth.Tensor(targets)}
dataset = synth.Spec("generalised-dice-masks", generator=masks, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("regression", split="train", input_field="inputs", target_field="targets", preserve_shape=True)
class Segmenter(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=16, out_features=32)
    def forward(self, inputs):
        logits = self.network(inputs.reshape(inputs.shape[0], -1)).reshape(-1, 2, 4, 4)
        return torch.softmax(logits, dim=1)
trainer = Trainer(Segmenter(), train, recipe="regression", recipe_config={"loss": "generalised-dice"}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
